// The stereo split channel mapping in show.config.json: a recording with
// Host 1 on the right channel is blocked by default and passes once the
// mapping says so. The slate is generated by ffmpeg at test time.
import test from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { spawnSync } from "node:child_process";
import { resolveTool } from "../platform_tools.mjs";
import { buildChannelPreflight } from "./channel_preflight.mjs";
import { stereoSplitDecodeArgs } from "./show_config.mjs";

test("stereo split channel mapping swaps which channel is measured as Host 1", () => {
  const dir = mkdtempSync(join(tmpdir(), "eaol-channel-mapping-"));
  const previous = process.env.EAOL_SHOW_CONFIG;
  try {
    const slate = join(dir, "slate.wav");
    const between = (from, to) => `between(t\\,${from}\\,${to})`;
    const tone = (hz) => `0.3*sin(2*PI*${hz}*t)`;
    const quiet = "0.0005*sin(2*PI*50*t)";
    // Host 1 speaks at 2-5s and is wired to the RIGHT channel; Host 2 speaks at 7-10s on the LEFT.
    const left = `${quiet}+${tone(220)}*${between(7, 9.999)}+${tone(220)}*${between(12, 14.999)}`;
    const right = `${quiet}+${tone(330)}*${between(2, 4.999)}+${tone(330)}*${between(12, 14.999)}`;
    const made = spawnSync(resolveTool("ffmpeg"), ["-v", "error", "-f", "lavfi", "-i", `aevalsrc=${left}|${right}:s=48000:d=17`, "-c:a", "pcm_s16le", "-y", slate], { encoding: "utf8" });
    assert.equal(made.status, 0, made.stderr);
    const stat = statSync(slate);
    const manifest = { sources: [{ id: "primary_camera", label: "Stereo split recording", path: slate, bytes: stat.size, modified_ms: Math.round(stat.mtimeMs), audio: { channels: 2 } }] };

    const config = (leftHost) => {
      const path = join(dir, `${leftHost}.json`);
      writeFileSync(path, JSON.stringify({ audio: { channel_mapping: { left: leftHost } } }));
      return path;
    };
    process.env.EAOL_SHOW_CONFIG = config("host_1");
    assert.deepEqual(stereoSplitDecodeArgs(), []);
    const blocked = buildChannelPreflight({ manifest });
    assert.equal(blocked.status, "blocked");
    assert.equal(blocked.checks.host_1_left_dominance, false);

    process.env.EAOL_SHOW_CONFIG = config("host_2");
    assert.equal(stereoSplitDecodeArgs().length, 2);
    const passed = buildChannelPreflight({ manifest });
    assert.equal(passed.status, "passed", JSON.stringify(passed.blocking));
  } finally {
    if (previous === undefined) delete process.env.EAOL_SHOW_CONFIG;
    else process.env.EAOL_SHOW_CONFIG = previous;
    rmSync(dir, { recursive: true, force: true });
  }
});
